1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30	)
31	
32	// FormatVersion is the only registry file format understood by this build.
33	const FormatVersion = 1
34	
35	// MaxQuantity is the inclusive upper bound for a batch quantity.
36	const MaxQuantity = int64(1<<63 - 1)
37	
38	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
39	
40	// Batch is the four-piece record of one supply-chain batch.
41	type Batch struct {
42		Batch    string `json:"batch"`
43		Product  string `json:"product"`
44		Quantity int64  `json:"quantity"`
45		Unit     string `json:"unit"`
46	}
47	
48	// Registry is the on-disk registry file.
49	type Registry struct {
50		Version int     `json:"version"`
51		Batches []Batch `json:"batches"`
52	}
53	
54	// Input is a normalized registration request.
55	type Input struct {
56		Batch    string
57		Product  string
58		Quantity int64
59		Unit     string
60	}
61	
62	// Outcome reports what Register did.
63	type Outcome struct {
64		Batch   Batch
65		Created bool // true when a record was added, false for an identical repeat
66	}
67	
68	// ConflictError reports that a batch id is already held by a different record.
69	// Fields lists every differing member among "product", "quantity" and "unit".
70	type ConflictError struct {
71		Batch  string
72		Fields []string
73	}
74	
75	func (e *ConflictError) Error() string {
76		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
77			e.Batch, strings.Join(e.Fields, ", "))
78	}
79	
80	// DuplicateIDError reports two stored records sharing one batch id.
81	type DuplicateIDError struct {
82		Batch string
83	}
84	
85	func (e *DuplicateIDError) Error() string {
86		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
87	}
88	
89	// NormalizeField trims leading and trailing whitespace; the result must stay
90	// non-empty. Interior characters, including interior whitespace, are kept,
91	// and casing is preserved so "B1" and "b1" are different values.
92	func NormalizeField(value string) (string, error) {
93		trimmed := strings.TrimSpace(value)
94		if trimmed == "" {
95			return "", errors.New("value must not be empty after trimming whitespace")
96		}
97		return trimmed, nil
98	}
99	
100	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
101	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
102	// compared. Zero, signs, fractions, non-ASCII digits and values above the
103	// signed 64-bit maximum are rejected.
104	func ParseQuantity(text string) (int64, error) {
105		if !quantityPattern.MatchString(text) {
106			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
107		}
108		value, err := strconv.ParseInt(text, 10, 64)
109		if err != nil {
110			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
111		}
112		if value == 0 {
113			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
114		}
115		return value, nil
116	}
117	
118	// Load reads the registry at path. A missing file yields an empty registry
119	// with existed == false. An existing file that is empty, not parseable as
120	// the public format, of an unsupported version, or holding duplicate batch
121	// ids is an error: callers must never overwrite such a file as if it were a
122	// fresh registry.
123	func Load(path string) (reg *Registry, existed bool, err error) {
124		data, err := os.ReadFile(path)
125		if err != nil {
126			if errors.Is(err, fs.ErrNotExist) {
127				return &Registry{Version: FormatVersion}, false, nil
128			}
129			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
130		}
131		if len(bytes.TrimSpace(data)) == 0 {
132			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
133		}
134		reg, err = decode(data)
135		if err != nil {
136			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
137		}
138		if err := validate(reg); err != nil {
139			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
140		}
141		return reg, true, nil
142	}
143	
144	func decode(data []byte) (*Registry, error) {
145		dec := json.NewDecoder(bytes.NewReader(data))
146		dec.DisallowUnknownFields()
147		reg := &Registry{}
148		if err := dec.Decode(reg); err != nil {
149			return nil, err
150		}
151		var extra json.RawMessage
152		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
153			if err == nil {
154				return nil, errors.New("unexpected data after registry object")
155			}
156			return nil, err
157		}
158		if reg.Version != FormatVersion {
159			return nil, fmt.Errorf("unsupported registry version: got %d, want %d", reg.Version, FormatVersion)
160		}
161		return reg, nil
162	}
163	
164	func validate(reg *Registry) error {
165		seen := make(map[string]struct{}, len(reg.Batches))
166		for i, b := range reg.Batches {
167			if b.Batch == "" || b.Product == "" || b.Unit == "" {
168				return fmt.Errorf("batches[%d] (batch %q): batch, product and unit must all be non-empty", i, b.Batch)
169			}
170			if b.Quantity <= 0 {
171				return fmt.Errorf("batches[%d] (batch %q): quantity must be a positive integer", i, b.Batch)
172			}
173			if _, dup := seen[b.Batch]; dup {
174				return &DuplicateIDError{Batch: b.Batch}
175			}
176			seen[b.Batch] = struct{}{}
177		}
178		return nil
179	}
180	
181	// ManifestRecordError reports a manifest record that is structurally invalid
182	// or carries a quantity outside the accepted range. Position is the record's
183	// 1-based position in the manifest.
184	type ManifestRecordError struct {
185		Position int
186		Batch    string // normalized batch id when available, otherwise ""
187		Reason   string
188	}
189	
190	func (e *ManifestRecordError) Error() string {
191		if e.Batch != "" {
192			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
193		}
194		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
195	}
196	
197	// ManifestConflictError reports that a manifest record disagrees with the
198	// record already registered, or introduced earlier in the same manifest,
199	// under the same batch id. Position is the record's 1-based position in the
200	// manifest and Fields lists every differing member among "product",
201	// "quantity" and "unit" in that order.
202	type ManifestConflictError struct {
203		Position int
204		Batch    string
205		Fields   []string
206		Source   string // "registry" or "manifest"
207		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
208	}
209	
210	func (e *ManifestConflictError) Error() string {
211		if e.Source == "manifest" {
212			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
213				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
214		}
215		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
216			e.Position, e.Batch, strings.Join(e.Fields, ", "))
217	}
218	
219	// ParseManifest decodes data as a non-empty JSON array holding exactly the
220	// four required fields batch, product, quantity and unit per element. The
221	// three text fields must be JSON strings that are not blank after trimming;
222	// quantity must be a JSON integer (no strings, fractions or exponents) in
223	// the range 1..MaxQuantity. An empty file, empty array, non-array document
224	// or any malformed record is rejected. The manifest bytes are never written.
225	func ParseManifest(data []byte) ([]Input, error) {
226		trimmed := bytes.TrimSpace(data)
227		if len(trimmed) == 0 {
228			return nil, errors.New("manifest file is empty")
229		}
230		if trimmed[0] != '[' {
231			return nil, errors.New("manifest must be a non-empty JSON array of records")
232		}
233	
234		var elems []json.RawMessage
235		dec := json.NewDecoder(bytes.NewReader(data))
236		if err := dec.Decode(&elems); err != nil {
237			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
238		}
239		var extra json.RawMessage
240		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
241			if err == nil {
242				return nil, errors.New("manifest has unexpected data after the array")
243			}
244			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
245		}
246		if len(elems) == 0 {
247			return nil, errors.New("manifest must contain at least one record")
248		}
249	
250		inputs := make([]Input, 0, len(elems))
251		for i, raw := range elems {
252			pos := i + 1
253			in, err := parseManifestRecord(raw)
254			if err != nil {
255				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
256			}
257			inputs = append(inputs, in)
258		}
259		return inputs, nil
260	}
261	
262	// requiredManifestFields are the only members a manifest record may carry.
263	var requiredManifestFields = map[string]struct{}{
264		"batch": {}, "product": {}, "quantity": {}, "unit": {},
265	}
266	
267	// parseManifestRecord validates one manifest element: it must be a JSON
268	// object with exactly the four required keys, text fields as non-blank
269	// strings and quantity as a strict JSON integer.
270	func parseManifestRecord(raw json.RawMessage) (Input, error) {
271		var in Input
272		if len(bytes.TrimSpace(raw)) == 0 || bytes.TrimSpace(raw)[0] != '{' {
273			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
274		}
275		fields := make(map[string]json.RawMessage)
276		if err := json.Unmarshal(raw, &fields); err != nil {
277			return in, fmt.Errorf("record is not valid JSON: %w", err)
278		}
279		for name := range fields {
280			if _, ok := requiredManifestFields[name]; !ok {
281				return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", name)
282			}
283		}
284		keys, err := objectKeys(raw)
285		if err != nil {
286			return in, err
287		}
288		counts := make(map[string]int, len(keys))
289		for _, k := range keys {
290			counts[k]++
291			if counts[k] > 1 {
292				return in, fmt.Errorf("record lists field %q more than once", k)
293			}
294		}
295	
296		textField := func(name string) (string, error) {
297			value, ok := fields[name]
298			if !ok {
299				return "", fmt.Errorf("missing required field %q", name)
300			}
301			var text string
302			if err := json.Unmarshal(value, &text); err != nil {
303				return "", fmt.Errorf("field %q must be a JSON string", name)
304			}
305			normalized, err := NormalizeField(text)
306			if err != nil {
307				return "", fmt.Errorf("field %q must not be blank: %w", name, err)
308			}
309			return normalized, nil
310		}
311	
312		in.Batch, err = textField("batch")
313		if err != nil {
314			return in, err
315		}
316		in.Product, err = textField("product")
317		if err != nil {
318			return in, err
319		}
320		in.Unit, err = textField("unit")
321		if err != nil {
322			return in, err
323		}
324		quantityRaw, ok := fields["quantity"]
325		if !ok {
326			return in, errors.New("missing required field \"quantity\"")
327		}
328		in.Quantity, err = parseManifestQuantity(bytes.TrimSpace(quantityRaw))
329		if err != nil {
330			return in, err
331		}
332		return in, nil
333	}
334	
335	// objectKeys returns the member keys of a JSON object in source order,
336	// flagging repeated names for the caller.
337	func objectKeys(raw json.RawMessage) ([]string, error) {
338		dec := json.NewDecoder(bytes.NewReader(raw))
339		if _, err := dec.Token(); err != nil { // opening brace
340			return nil, fmt.Errorf("record is not a JSON object: %w", err)
341		}
342		var keys []string
343		for dec.More() {
344			tok, err := dec.Token()
345			if err != nil {
346				return nil, err
347			}
348			key, ok := tok.(string)
349			if !ok {
350				return nil, errors.New("record object keys must be JSON strings")
351			}
352			keys = append(keys, key)
353			// Skip over the value token(s) so the next token is the next key.
354			var skip json.RawMessage
355			if err := dec.Decode(&skip); err != nil {
356				return nil, err
357			}
358		}
359		if _, err := dec.Token(); err != nil { // closing brace
360			return nil, err
361		}
362		return keys, nil
363	}
364	
365	// parseManifestQuantity accepts exactly a strict JSON integer token in the
366	// range 1..MaxQuantity. Strings, signs, fractions, exponents, leading zeros
367	// and out-of-range values are rejected instead of silently rounded.
368	func parseManifestQuantity(token []byte) (int64, error) {
369		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
370			return 0, fmt.Errorf("field %q must be a JSON integer between 1 and %d", "quantity", MaxQuantity)
371		}
372		for _, c := range token {
373			if c < '0' || c > '9' {
374				return 0, fmt.Errorf("field %q must be a JSON integer without sign, fraction or exponent", "quantity")
375			}
376		}
377		if len(token) > 1 && token[0] == '0' {
378			return 0, errors.New("field \"quantity\" must be a JSON integer without leading zeros")
379		}
380		value, err := strconv.ParseInt(string(token), 10, 64)
381		if err != nil {
382			return 0, fmt.Errorf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)
383		}
384		if value == 0 {
385			return 0, errors.New("field \"quantity\" must be greater than zero")
386		}
387		return value, nil
388	}
389	
390	// ImportResult is one entry of an Import outcome: the normalized record in
391	// manifest order plus whether it was newly created or already present.
392	type ImportResult struct {
393		Batch   Batch
394		Created bool
395	}
396	
397	// Import validates every record of inputs before appending anything: the
398	// whole manifest fails if any record conflicts with a stored record or with
399	// an earlier manifest record, and reg is left untouched on error. New batch
400	// ids are appended in first-occurrence order; an id already stored or
401	// introduced earlier in the same manifest is confirmed as a duplicate only
402	// when product, quantity and unit all match. Results come back in manifest
403	// order; Created is false for duplicates.
404	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
405		if reg.Version != FormatVersion {
406			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
407		}
408		if len(inputs) == 0 {
409			return nil, errors.New("manifest must contain at least one record")
410		}
411	
412		// Work on a copy: a rejected manifest must never partially land in reg.
413		working := append([]Batch(nil), reg.Batches...)
414		indexByID := make(map[string]int, len(working))
415		for i, b := range working {
416			indexByID[b.Batch] = i
417		}
418		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
419	
420		out := make([]ImportResult, len(inputs))
421		for i, in := range inputs {
422			pos := i + 1
423			if idx, known := indexByID[in.Batch]; known {
424				existing := working[idx]
425				diffs := diffFields(existing, in)
426				if len(diffs) > 0 {
427					if prev, inManifest := firstPos[in.Batch]; inManifest {
428						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
429					}
430					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
431				}
432				out[i] = ImportResult{Batch: existing, Created: false}
433				continue
434			}
435			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
436			working = append(working, b)
437			indexByID[in.Batch] = len(working) - 1
438			firstPos[in.Batch] = pos
439			out[i] = ImportResult{Batch: b, Created: true}
440		}
441	
442		reg.Batches = working
443		return out, nil
444	}
445	
446	// diffFields lists the members of product, quantity and unit in which in
447	// differs from existing, in that fixed order.
448	func diffFields(existing Batch, in Input) []string {
449		var diffs []string
450		if existing.Product != in.Product {
451			diffs = append(diffs, "product")
452		}
453		if existing.Quantity != in.Quantity {
454			diffs = append(diffs, "quantity")
455		}
456		if existing.Unit != in.Unit {
457			diffs = append(diffs, "unit")
458		}
459		return diffs
460	}
461	
462	// Register adds in to reg, or confirms the identical record already stored
463	// under the same batch id. A batch id held by a record differing in product,
464	// quantity or unit produces a *ConflictError and leaves reg untouched. The
465	// zero Outcome is returned together with the error.
466	func Register(reg *Registry, in Input) (Outcome, error) {
467		if reg.Version != FormatVersion {
468			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
469		}
470		if in.Batch == "" || in.Product == "" || in.Unit == "" {
471			return Outcome{}, errors.New("batch, product and unit must be non-empty")
472		}
473		if in.Quantity <= 0 || in.Quantity > MaxQuantity {
474			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
475		}
476		for _, b := range reg.Batches {
477			if b.Batch != in.Batch {
478				continue
479			}
480			var diffs []string
481			if b.Product != in.Product {
482				diffs = append(diffs, "product")
483			}
484			if b.Quantity != in.Quantity {
485				diffs = append(diffs, "quantity")
486			}
487			if b.Unit != in.Unit {
488				diffs = append(diffs, "unit")
489			}
490			if len(diffs) > 0 {
491				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
492			}
493			return Outcome{Batch: b, Created: false}, nil
494		}
495		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
496		reg.Batches = append(reg.Batches, b)
497		return Outcome{Batch: b, Created: true}, nil
498	}
499	
500	// Save atomically writes reg to path, replacing the file only after the new
501	// content is fully on disk so an existing registry stays usable on failure.
502	// Records are serialized in their current order; the file is created with
503	// 0644 permissions or, when replacing an existing file, with its permissions.
504	func Save(path string, reg *Registry) error {
505		if reg.Version != FormatVersion {
506			return fmt.Errorf("cannot write registry format version %d", reg.Version)
507		}
508		mode := os.FileMode(0o644)
509		if info, err := os.Stat(path); err == nil {
510			mode = info.Mode().Perm()
511		} else if !errors.Is(err, fs.ErrNotExist) {
512			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
513		}
514	
515		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
516			return fmt.Errorf("cannot save registry %q: %w", path, err)
517		}
518	
519		var buf bytes.Buffer
520		enc := json.NewEncoder(&buf)
521		enc.SetEscapeHTML(false)
522		enc.SetIndent("", "  ")
523		if err := enc.Encode(reg); err != nil {
524			return fmt.Errorf("cannot encode registry %q: %w", path, err)
525		}
526	
527		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
528		if err != nil {
529			return fmt.Errorf("cannot save registry %q: %w", path, err)
530		}
531		tmpName := tmp.Name()
532		abort := func(cause error) error {
533			tmp.Close()
534			os.Remove(tmpName)
535			return fmt.Errorf("cannot save registry %q: %w", path, cause)
536		}
537		if _, err := tmp.Write(buf.Bytes()); err != nil {
538			return abort(err)
539		}
540		if err := tmp.Chmod(mode); err != nil {
541			return abort(err)
542		}
543		if err := tmp.Sync(); err != nil {
544			return abort(err)
545		}
546		if err := tmp.Close(); err != nil {
547			os.Remove(tmpName)
548			return fmt.Errorf("cannot save registry %q: %w", path, err)
549		}
550		if err := os.Rename(tmpName, path); err != nil {
551			os.Remove(tmpName)
552			return fmt.Errorf("cannot save registry %q: %w", path, err)
553		}
554		return nil
555	}
