// FormatError reports a structural violation of the public registry format:
// a missing, duplicated, misspelled or mistyped field, either in the root
// object (Position == 0) or in one batch record (Position is its 1-based
// index in "batches"). Batch carries the record's batch id when it is
// uniquely determined; it stays empty when the "batch" member itself is
// missing, duplicated or not a string.
type FormatError struct {
	Position int
	Batch    string
	Field    string
	Reason   string
}

func (e *FormatError) Error() string {
	var where string
	if e.Position > 0 {
		where = fmt.Sprintf("batches record %d", e.Position)
		if e.Batch != "" {
			where += fmt.Sprintf(" (batch %q)", e.Batch)
		}
	} else {
		where = "root object"
	}
	if e.Field != "" {
		return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
	}
	return fmt.Sprintf("%s: %s", where, e.Reason)
}
