type objectField struct {
	key   string
	value json.RawMessage
}

// parseObjectFields decodes one JSON object value into its members in source
// order. Keys are compared after JSON string decoding, so escaped spellings
// of the same name ("bat\u0063h") are seen as the same field. The raw is
// already known to be a single JSON value.
func parseObjectFields(raw []byte) ([]objectField, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return nil, errors.New("value is not a JSON object")
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	if _, err := dec.Token(); err != nil {
		return nil, err
	}
	var fields []objectField
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		key, ok := tok.(string)
		if !ok {
			return nil, errors.New("object keys must be JSON strings")
		}
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, err
		}
		fields = append(fields, objectField{key: key, value: value})
	}
	if _, err := dec.Token(); err != nil {
		return nil, err
	}
	return fields, nil
}
